import{_ as a,o as i,c as t,a2 as o}from"./chunks/framework.sc8Z_ZE3.js";const f=JSON.parse('{"title":"Code style","description":"","frontmatter":{},"headers":[],"relativePath":"contribute/code-style.md","filePath":"contribute/code-style.md"}'),n={name:"contribute/code-style.md"};function r(s,e,l,d,c,h){return i(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="code-style" tabindex="-1">Code style <a class="header-anchor" href="#code-style" aria-label="Permalink to &quot;Code style&quot;">​</a></h1><p>These rules apply to people and coding agents alike.</p><h2 id="files-and-folders" tabindex="-1">Files and folders <a class="header-anchor" href="#files-and-folders" aria-label="Permalink to &quot;Files and folders&quot;">​</a></h2><ul><li><strong>About 300 lines per file</strong>, at most 500. Do not add behaviour to a file that is already over the target: create the focused module the code belongs in and wire it in with a small edit.</li><li><strong>Group by responsibility.</strong> One module for transport, one for business logic, one for policies and constants; in the web app one for state and one for presentation.</li><li><strong>No catch-all helper files</strong> and no folders full of single-use files without a real boundary.</li><li><strong>Keep route handlers thin.</strong> Business logic lives in services, runtime mechanics in the agent layer, tool capabilities with the tools.</li></ul><h2 id="language-and-names" tabindex="-1">Language and names <a class="header-anchor" href="#language-and-names" aria-label="Permalink to &quot;Language and names&quot;">​</a></h2><ul><li>English only in code, comments, log messages and anything an agent reads.</li><li>Clear names that say what a thing is or does. No abbreviations a newcomer has to guess.</li></ul><h2 id="decisions-are-explicit" tabindex="-1">Decisions are explicit <a class="header-anchor" href="#decisions-are-explicit" aria-label="Permalink to &quot;Decisions are explicit&quot;">​</a></h2><p>Octryx AI is built to be deterministic and governable. Execution decisions come from explicit profiles, policies and configuration, never from guessing intent with keywords or from silent fallbacks. An unclear decision becomes an explicit state: denied, needs approval, needs configuration or needs clarification.</p><h2 id="forbidden-patterns" tabindex="-1">Forbidden patterns <a class="header-anchor" href="#forbidden-patterns" aria-label="Permalink to &quot;Forbidden patterns&quot;">​</a></h2><p>Unless the task requires it and the reason is written down:</p><ul><li>new oversized files, and catch-all helpers for unrelated logic;</li><li>silent changes to an API or data contract;</li><li>hard-coded secrets or insecure defaults;</li><li>broad <code>except Exception</code> without a clear boundary;</li><li>cleanup mixed into feature work;</li><li>tool risk, approvals or write behaviour inferred only from a tool&#39;s name;</li><li>connector tools visible when the connector is not active for the Workspace;</li><li>credentials, tokens or credentialed clone URLs passed through generic tool or runtime paths;</li><li>SQL written by a model and executed as a database tool.</li></ul><h2 id="refactoring-a-big-file" tabindex="-1">Refactoring a big file <a class="header-anchor" href="#refactoring-a-big-file" aria-label="Permalink to &quot;Refactoring a big file&quot;">​</a></h2><p>Extract one responsibility at a time, in this order: pure helpers, state, side effects and integrations, then rendering or transport glue. Verify behaviour after each step. Do not mix feature work, renaming, formatting and moves in one change.</p>',13)])])}const p=a(n,[["render",r]]);export{f as __pageData,p as default};
